Connect-Entra -Scopes 'Application.Read.All'
try {
    $blueprint = Get-EntraBetaAgentIdentityBlueprint -BlueprintId "aaaaaaaa-0000-1111-2222-bbbbbbbbbbbb"
    Write-Host "Blueprint found: $($blueprint.displayName)"
} catch {
    Write-Host "Blueprint not found or error occurred: $_"
}

Connect-Entra -Scopes 'Application.Read.All'
try {
    $sp = Get-EntraBetaAgentIdentityBlueprintPrincipal -ServicePrincipalId "aaaaaaaa-0000-1111-2222-bbbbbbbbbbbb"
    Write-Host "Service Principal found: $($sp.displayName)"
} catch {
    Write-Host "Service Principal not found or error occurred: $_"
}

Connect-Entra -Scopes 'Application.Read.All'
$apps = Get-EntraBetaApplication -All
$appsWithoutOwners = @()
foreach ($app in $apps) {
    try {
        $owners = Get-EntraBetaApplicationOwner -ApplicationId $app.Id
        if (-not $owners) {
            $appsWithoutOwners += $app
        }
    }
    catch {
        Write-Warning "Failed to check owners for app: $($app.DisplayName)"
    }

    # Optional: throttle to avoid rate limits (especially in large tenants)
    #Start-Sleep -Milliseconds 100
}
$appsWithoutOwners | Select-Object DisplayName, Id, AppId

Connect-Entra -Scopes 'Application.ReadWrite.All', 'Application.ReadWrite.OwnedBy'
$app = Get-EntraBetaApplication -Filter "DisplayName eq '<application-display-name>'"
$params = @{
    ApplicationId      = $app.Id
    KeyCredential      = @{ key = [System.Convert]::FromBase64String('{base64cert}') }
    PasswordCredential = @{ DisplayName = 'mypassword' }
    Proof              = '{token}'
}
New-EntraBetaApplicationKey @params

Connect-Entra -Scopes 'Application.ReadWrite.All','Application.ReadWrite.OwnedBy'
$application = Get-EntraBetaApplication -Filter "DisplayName eq 'Helpdesk Application'"
$params = @{
    AccountEnabled = $true 
    AppId = $application.AppId 
    AppRoleAssignmentRequired = $true 
    DisplayName = $application.DisplayName 
    Tags = {WindowsAzureActiveDirectoryIntegratedApp}
}
New-EntraBetaServicePrincipal @params
